import { rng } from "../photo/synth";

/** 16-joint human model (metres, Y up, +Z forward, +X to the person's left). Skeleton positions are generated by forward kinematics from joint angles; point clouds are sampled on capsules around the bones. */
export const JOINTS = ["pelvis", "spine", "neck", "head", "l_shoulder", "r_shoulder", "l_elbow", "r_elbow", "l_wrist", "r_wrist", "l_hip", "r_hip", "l_knee", "r_knee", "l_ankle", "r_ankle"] as const;
export type JointName = (typeof JOINTS)[number];
export const J = Object.fromEntries(JOINTS.map((n, i) => [n, i])) as Record<JointName, number>;
export const JOINT_LABEL: Record<JointName, string> = { pelvis: "Pelvis", spine: "Spine", neck: "Neck", head: "Head", l_shoulder: "Left shoulder", r_shoulder: "Right shoulder", l_elbow: "Left elbow", r_elbow: "Right elbow", l_wrist: "Left wrist", r_wrist: "Right wrist", l_hip: "Left hip", r_hip: "Right hip", l_knee: "Left knee", r_knee: "Right knee", l_ankle: "Left ankle", r_ankle: "Right ankle" };
export type V3 = [number, number, number];
/** Bones: [from, to, capsule radius]. */
export const BONES: [JointName, JointName, number][] = [
  ["pelvis", "spine", 0.16], ["spine", "neck", 0.15], ["neck", "head", 0.06],
  ["neck", "l_shoulder", 0.05], ["neck", "r_shoulder", 0.05], ["l_shoulder", "l_elbow", 0.05], ["r_shoulder", "r_elbow", 0.05], ["l_elbow", "l_wrist", 0.04], ["r_elbow", "r_wrist", 0.04],
  ["pelvis", "l_hip", 0.08], ["pelvis", "r_hip", 0.08], ["l_hip", "l_knee", 0.08], ["r_hip", "r_knee", 0.08], ["l_knee", "l_ankle", 0.06], ["r_knee", "r_ankle", 0.06],
];
export const BONE_IDX = BONES.map(([a, b, r]) => [J[a], J[b], r] as [number, number, number]);
const LEN = { spine: 0.25, chest: 0.25, head: 0.2, clav: 0.19, upper: 0.3, fore: 0.26, hip: 0.1, thigh: 0.43, shin: 0.43 };
export interface Pose { root: V3; heading: number; trunk: number; hipFlex: [number, number]; hipAbd: [number, number]; knee: [number, number]; shFlex: [number, number]; shAbd: [number, number]; elbow: [number, number]; extraY?: number }
const rotY = (v: V3, a: number): V3 => [v[0] * Math.cos(a) + v[2] * Math.sin(a), v[1], -v[0] * Math.sin(a) + v[2] * Math.cos(a)];
const rotX = (v: V3, a: number): V3 => [v[0], v[1] * Math.cos(a) - v[2] * Math.sin(a), v[1] * Math.sin(a) + v[2] * Math.cos(a)];
const rotZ = (v: V3, a: number): V3 => [v[0] * Math.cos(a) - v[1] * Math.sin(a), v[0] * Math.sin(a) + v[1] * Math.cos(a), v[2]];
const add = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
/** Forward kinematics: joint angles (radians) -> 16 joint positions. Flexion swings a limb forward (+Z); abduction raises/spreads it sideways; knee and elbow bend the lower segment (knee backward, elbow forward). */
export function fk(p: Pose, scale = 1): V3[] {
  const L = Object.fromEntries(Object.entries(LEN).map(([k, v]) => [k, v * scale])) as typeof LEN, out: V3[] = new Array(16);
  const local: V3[] = new Array(16); local[J.pelvis] = [0, 0, 0];
  const tr = (v: V3) => rotX(v, p.trunk); local[J.spine] = tr([0, L.spine, 0]); local[J.neck] = add(local[J.spine], tr([0, L.chest, 0])); local[J.head] = add(local[J.neck], tr([0, L.head, 0]));
  for (const [s, sgn] of [["l", 1], ["r", -1]] as const) {
    const i = s === "l" ? 0 : 1; local[J[`${s}_shoulder` as JointName]] = add(local[J.neck], tr([sgn * L.clav, -0.03, 0]));
    const arm = (flex: number, abd: number, d: number): V3 => rotZ(rotX([0, -d, 0], flex), sgn * abd);
    const up = arm(p.shFlex[i], p.shAbd[i], L.upper); local[J[`${s}_elbow` as JointName]] = add(local[J[`${s}_shoulder` as JointName]], up);
    const fore = rotZ(rotX([0, -L.fore, 0], p.shFlex[i] + p.elbow[i]), sgn * p.shAbd[i]); local[J[`${s}_wrist` as JointName]] = add(local[J[`${s}_elbow` as JointName]], fore);
    local[J[`${s}_hip` as JointName]] = [sgn * LEN.hip * scale, -0.05 * scale, 0];
    const th = rotZ(rotX([0, -L.thigh, 0], p.hipFlex[i]), sgn * p.hipAbd[i]); local[J[`${s}_knee` as JointName]] = add(local[J[`${s}_hip` as JointName]], th);
    const sh = rotZ(rotX([0, -L.shin, 0], p.hipFlex[i] - p.knee[i]), sgn * p.hipAbd[i]); local[J[`${s}_ankle` as JointName]] = add(local[J[`${s}_knee` as JointName]], sh);
  }
  let low = Infinity; for (const n of ["l_ankle", "r_ankle"] as const) low = Math.min(low, local[J[n]][1]);
  const lift = -low + 0.075 + (p.extraY ?? 0); // keep the lower foot on the floor (plus any jump height)
  for (let k = 0; k < 16; k++) { const v = rotY(local[k], p.heading); out[k] = [p.root[0] + v[0], p.root[1] + lift + v[1], p.root[2] + v[2]]; } return out;
}
const d2r = Math.PI / 180, S = Math.sin, Cs = Math.cos;
export const MOTIONS = {
  walk: { label: "Walking", period: 1.1 },
  squat: { label: "Squat", period: 2.4 },
  jacks: { label: "Jumping jacks", period: 1.0 },
  jump: { label: "Vertical jump", period: 2.2 },
  kick: { label: "Kick", period: 1.6 },
  stand: { label: "Standing still", period: 2 },
} as const;
export type MotionKey = keyof typeof MOTIONS;
export function poseAt(m: MotionKey, t: number, start: V3, heading: number): Pose {
  const w = (2 * Math.PI * t) / MOTIONS[m].period, z = (a: number): [number, number] => [a, a]; const base: Pose = { root: [...start], heading, trunk: 0, hipFlex: [0, 0], hipAbd: [0, 0], knee: [0, 0], shFlex: [0, 0], shAbd: [0.06, 0.06], elbow: [0.12, 0.12] };
  if (m === "walk") { const s = S(w), c = Cs(w); const fwd: V3 = rotY([0, 0, 1], heading); const d = 1.15 * t; return { ...base, root: [start[0] + fwd[0] * d, start[1], start[2] + fwd[2] * d], hipFlex: [28 * d2r * s, -28 * d2r * s], knee: [Math.max(0, c) * 50 * d2r + 4 * d2r, Math.max(0, -c) * 50 * d2r + 4 * d2r], shFlex: [-22 * d2r * s, 22 * d2r * s], elbow: [(20 + 10 * Math.abs(s)) * d2r, (20 + 10 * Math.abs(s)) * d2r], trunk: 4 * d2r, extraY: 0.015 * Math.abs(c) }; }
  if (m === "squat") { const k = (1 - Cs(w)) / 2; return { ...base, trunk: 32 * d2r * k, hipFlex: z(88 * d2r * k), knee: z(102 * d2r * k), shFlex: z(75 * d2r * k), elbow: z(8 * d2r) }; }
  if (m === "jacks") { const k = (1 - Cs(w)) / 2; return { ...base, shAbd: z((8 + 150 * k) * d2r), hipAbd: z(22 * d2r * k), knee: z(8 * d2r), elbow: z(10 * d2r), extraY: 0.12 * Math.max(0, S(w)) * k }; }
  if (m === "jump") { const u = (t % MOTIONS.jump.period) / MOTIONS.jump.period; const crouch = u < 0.3 ? Math.sin((u / 0.3) * (Math.PI / 2)) : u < 0.4 ? 1 - (u - 0.3) / 0.1 : 0; const air = u >= 0.4 && u < 0.7 ? (u - 0.4) / 0.3 : -1; const h = air >= 0 ? 0.38 * 4 * air * (1 - air) : 0; const land = u >= 0.7 && u < 0.85 ? Math.sin(((u - 0.7) / 0.15) * Math.PI) * 0.7 : 0; const k = Math.max(crouch, land);
    return { ...base, trunk: 28 * d2r * k, hipFlex: z(80 * d2r * k), knee: z((air >= 0 ? 15 : 95 * k) * d2r), shFlex: z((air >= 0 ? 150 : -35 + 60 * k) * d2r), extraY: h }; }
  if (m === "kick") { const u = (t % MOTIONS.kick.period) / MOTIONS.kick.period, a = u < 0.3 ? S((u / 0.3) * (Math.PI / 2)) : u < 0.55 ? 1 : u < 0.85 ? 1 - (u - 0.55) / 0.3 : 0; const ext = u < 0.3 ? 1 : u < 0.55 ? 1 - Math.min(1, (u - 0.3) / 0.12) : 1;
    return { ...base, trunk: -10 * d2r * a, hipFlex: [4 * d2r, 78 * d2r * a], knee: [10 * d2r, (a > 0 ? (95 - 90 * (1 - ext)) * d2r * (u < 0.3 ? a : 1) : 0) + (u >= 0.55 ? 40 * d2r * a : 0)], shAbd: [(30 * a + 6) * d2r, (30 * a + 6) * d2r] }; }
  return { ...base, shFlex: [0.02 * S(w), 0.02 * S(w)] };
}
export interface PersonSpec { motion: MotionKey; start: V3; heading: number; height?: number }
export interface Dataset { id: string; label: string; description: string; people: PersonSpec[]; sensor: "front" | "multi"; frames: number; fps: number; clutter: boolean }
export const DATASETS: Dataset[] = [
  { id: "walk", label: "Walking (multi-view scan)", description: "One person walks 3.4 m along +Z. Points cover all sides, as from a 360° capture rig.", people: [{ motion: "walk", start: [0, 0, -1.6], heading: 0 }], sensor: "multi", frames: 60, fps: 20, clutter: true },
  { id: "squat", label: "Squat (single depth camera)", description: "One person squats. Only the side facing a single depth camera is captured, so limbs are partly hidden.", people: [{ motion: "squat", start: [0, 0, 0], heading: 0 }], sensor: "front", frames: 60, fps: 20, clutter: true },
  { id: "jacks", label: "Jumping jacks (multi-view)", description: "Arms and legs open and close with a small hop.", people: [{ motion: "jacks", start: [0, 0, 0], heading: 0 }], sensor: "multi", frames: 60, fps: 20, clutter: false },
  { id: "jump", label: "Vertical jump (multi-view)", description: "Crouch, take off, flight and landing.", people: [{ motion: "jump", start: [0, 0, 0], heading: 0 }], sensor: "multi", frames: 48, fps: 20, clutter: false },
  { id: "kick", label: "Kick (single depth camera)", description: "Right-leg kick while balancing on the left leg.", people: [{ motion: "kick", start: [0, 0, 0], heading: 0 }], sensor: "front", frames: 48, fps: 20, clutter: false },
  { id: "two", label: "Two people (multi-view): walking and squatting", description: "Two people in the scene, tracked separately.", people: [{ motion: "walk", start: [-0.9, 0, -1.4], heading: 0, height: 1.75 }, { motion: "squat", start: [1.2, 0, 0.2], heading: -0.6, height: 1.62 }], sensor: "multi", frames: 60, fps: 20, clutter: true },
];
export interface Frame { points: Float32Array; truth: V3[][] /* per person */ }
const gauss = (r: () => number) => Math.sqrt(-2 * Math.log(Math.max(r(), 1e-12))) * Math.cos(2 * Math.PI * r());
/** Samples points on the capsule surfaces of one skeleton (cylinder sides plus hemisphere ends, area weighted), plus a head sphere and simple feet. Returns xyz with outward normals for visibility tests. */
function sampleBody(j: V3[], r: () => number, density: number, scale: number): { p: number[]; n: number[] } {
  const p: number[] = [], n: number[] = [], seg = (a: V3, b: V3, rad: number) => {
    const ax: V3 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], len = Math.hypot(ax[0], ax[1], ax[2]) || 1e-6, u: V3 = [ax[0] / len, ax[1] / len, ax[2] / len]; const t1: V3 = Math.abs(u[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0]; let e1: V3 = [u[1] * t1[2] - u[2] * t1[1], u[2] * t1[0] - u[0] * t1[2], u[0] * t1[1] - u[1] * t1[0]]; const l1 = Math.hypot(...e1); e1 = [e1[0] / l1, e1[1] / l1, e1[2] / l1]; const e2: V3 = [u[1] * e1[2] - u[2] * e1[1], u[2] * e1[0] - u[0] * e1[2], u[0] * e1[1] - u[1] * e1[0]];
    const nSide = Math.round(2 * Math.PI * rad * len * density), nCap = Math.round(4 * Math.PI * rad * rad * density);
    for (let i = 0; i < nSide; i++) { const th = r() * 2 * Math.PI, s = r(), c = Math.cos(th), sn = Math.sin(th); const nv: V3 = [c * e1[0] + sn * e2[0], c * e1[1] + sn * e2[1], c * e1[2] + sn * e2[2]]; p.push(a[0] + ax[0] * s + nv[0] * rad, a[1] + ax[1] * s + nv[1] * rad, a[2] + ax[2] * s + nv[2] * rad); n.push(...nv); }
    for (let i = 0; i < nCap; i++) { let x = gauss(r), y = gauss(r), z = gauss(r); const l = Math.hypot(x, y, z) || 1; x /= l; y /= l; z /= l; const end = x * u[0] + y * u[1] + z * u[2] > 0 ? b : a; p.push(end[0] + x * rad, end[1] + y * rad, end[2] + z * rad); n.push(x, y, z); }
  };
  for (const [a, b, rad] of BONE_IDX) seg(j[a], j[b], rad * scale);
  seg([j[J.head][0], j[J.head][1] + 0.07 * scale, j[J.head][2]], [j[J.head][0], j[J.head][1] + 0.08 * scale, j[J.head][2]], 0.1 * scale); // head
  for (const s of ["l", "r"] as const) { const a = j[J[`${s}_ankle` as JointName]]; seg(a, [a[0], a[1] - 0.05 * scale, a[2] + 0.2 * scale], 0.045 * scale); }
  return { p, n };
}
export function generateDataset(ds: Dataset, seed = 1): Frame[] {
  const r = rng(seed), frames: Frame[] = []; const sensor: V3 = [0.3, 1.5, 6];
  for (let f = 0; f < ds.frames; f++) {
    const t = f / ds.fps, pts: number[] = [], truth: V3[][] = [];
    for (const pe of ds.people) {
      const scale = (pe.height ?? 1.75) / 1.75, joints = fk(poseAt(pe.motion, t, pe.start, pe.heading), scale); truth.push(joints); const b = sampleBody(joints, r, 1400 / (scale * scale), scale);
      for (let i = 0; i < b.p.length; i += 3) { if (ds.sensor === "front") { const vx = sensor[0] - b.p[i], vy = sensor[1] - b.p[i + 1], vz = sensor[2] - b.p[i + 2]; if (vx * b.n[i] + vy * b.n[i + 1] + vz * b.n[i + 2] < 0) continue; } pts.push(b.p[i] + 0.006 * gauss(r), b.p[i + 1] + 0.006 * gauss(r), b.p[i + 2] + 0.006 * gauss(r)); }
    }
    for (let i = 0; i < 2600; i++) pts.push(-2.6 + r() * 5.6, 0.002 * gauss(r), -2.6 + r() * 6.6); // floor
    if (ds.clutter) { for (let i = 0; i < 700; i++) pts.push(-2.3 + (r() - 0.5) * 0.4, r() * 2.6, -1.2 + (r() - 0.5) * 0.4); for (let i = 0; i < 500; i++) pts.push(2.4 + (r() - 0.5) * 0.5, r() * 0.8, 1.6 + (r() - 0.5) * 0.5); } // a pillar and a low box that must not be mistaken for people
    for (let i = 0; i < 40; i++) pts.push(-2.6 + r() * 5.6, r() * 2.5, -2.6 + r() * 6.6); // stray points
    frames.push({ points: Float32Array.from(pts), truth });
  }
  return frames;
}
